-- JJ University catalog seed.
-- Generated by scripts/export-supabase-seed.mjs.
-- Run after supabase/jju_core_schema.sql.

begin;

on conflict (id) do update set
  slug = excluded.slug,
  title = excluded.title,
  subtitle = excluded.subtitle,
  creator = excluded.creator,
  description = excluded.description,
  status = excluded.status,
  visibility = excluded.visibility,
  archive_category = excluded.archive_category,
  primary_category = excluded.primary_category,
  cover_file = excluded.cover_file,
  book_file = excluded.book_file,
  content_key = excluded.content_key,
  word_count = excluded.word_count,
  reading_minutes = excluded.reading_minutes,
  reading_label = excluded.reading_label,
  chapter_count = excluded.chapter_count,
  tags = excluded.tags,
  slug_aliases = excluded.slug_aliases,
  metadata = excluded.metadata;

on conflict (alias) do update set
  book_id = excluded.book_id;

on conflict (id) do update set
  slug = excluded.slug,
  title = excluded.title,
  description = excluded.description,
  level = excluded.level,
  kind = excluded.kind,
  tags = excluded.tags,
  published = excluded.published,
  sort_order = excluded.sort_order,
  metadata = excluded.metadata;

on conflict (series_id, book_id) do update set
  position = excluded.position,
  note = excluded.note;

on conflict (slug) do update set
  title = excluded.title,
  kicker = excluded.kicker,
  subtitle = excluded.subtitle,
  description = excluded.description,
  status = excluded.status,
  price_cents = excluded.price_cents,
  stripe_price_id = excluded.stripe_price_id,
  lulu_project_id = excluded.lulu_project_id,
  lulu_pod_package_id = excluded.lulu_pod_package_id,
  public_interior_url = excluded.public_interior_url,
  public_cover_url = excluded.public_cover_url,
  metadata = excluded.metadata;

on conflict (product_slug, book_id) do update set
  position = excluded.position;

commit;
