insert into public.series (id, slug, title, description, level, kind, tags, published, sort_order, metadata)
values
('the-architects', 'the-architects', 'The Architects', 'Builders, founders, platform-makers, industrialists, and tech bosses who shaped the modern machine.', 'intermediate', 'series', array['Biography', 'Business & Economics', 'Capitalism & Corporations', 'Digital Culture & Technology', 'Technology & Innovation']::text[], true, 0, '{"sourceId":"the-architects","type":"series"}'::jsonb),
('the-code-breakers', 'the-code-breakers', 'The Code Breakers', 'Scientists, psychologists, inventors, and pattern-breakers who changed how reality gets explained.', 'intermediate', 'series', array['Biography', 'Science History', 'Physics & Cosmology', 'Psychology & Human Behavior', 'Technology & Innovation']::text[], true, 1, '{"sourceId":"the-code-breakers","type":"series"}'::jsonb),
('the-conquerors', 'the-conquerors', 'The Conquerors', 'Kings, emperors, commanders, and empire-builders who moved history by force.', 'intermediate', 'series', array['Biography', 'Military History', 'War & Conflict', 'Ancient Civilizations', 'Authoritarianism & Dictatorship']::text[], true, 2, '{"sourceId":"the-conquerors","type":"series"}'::jsonb),
('the-tyrants', 'the-tyrants', 'The Tyrants', 'Dictators, strongmen, propaganda states, and political machines built around control.', 'advanced', 'series', array['Authoritarianism & Dictatorship', 'Biography', 'Propaganda & Social Control', '20th Century', 'War & Conflict']::text[], true, 3, '{"sourceId":"the-tyrants","type":"series"}'::jsonb),
('god-struck', 'god-struck', 'God-struck', 'Prophets, mystics, saints, gurus, spiritual rebels, and people hit hard by the sacred.', 'intermediate', 'series', array['Biography', 'Religion & Spirituality', 'Spirituality & Mysticism', 'World Religions']::text[], true, 4, '{"sourceId":"god-struck","type":"series"}'::jsonb),
('the-disruptors', 'the-disruptors', 'The Disruptors', 'Reformers, revolutionaries, abolitionists, and social detonators who broke the expected order.', 'intermediate', 'series', array['Biography', 'Civil Rights & Social Justice', 'Revolution & Social Change', 'Social Movements']::text[], true, 5, '{"sourceId":"the-disruptors","type":"series"}'::jsonb),
('world-religions', 'world-religions', 'World Religions', 'Religious histories, movements, traditions, and belief systems outside the scripture guide series.', 'intermediate', 'series', array['World Religions', 'Religion & Spirituality', 'Christianity', 'Islam', 'Buddhism']::text[], true, 6, '{"sourceId":"world-religions","type":"series"}'::jsonb),
('the-philosophers', 'the-philosophers', 'The Philosophers', 'The core philosophy shelf: ancient questions, modern doubt, ethics, mind, meaning, and reality.', 'intermediate', 'series', array['Philosophy', 'Biography', 'Political Theory', 'Psychology & Human Behavior']::text[], true, 7, '{"sourceId":"the-philosophers","type":"series"}'::jsonb),
('red-white-and-bruised', 'red-white-and-bruised', 'Red, White, and Bruised', 'America through power, myth, corruption, surveillance, race, elections, and institutional damage.', 'intermediate', 'series', array['American History', 'American Politics', 'Government & Politics', 'Propaganda & Social Control', 'Civil Rights & Social Justice']::text[], true, 8, '{"sourceId":"red-white-and-bruised","type":"series"}'::jsonb),
('the-system', 'the-system', 'The System', 'The invisible machinery: bureaucracy, markets, platforms, funnels, institutions, and modern control loops.', 'intermediate', 'series', array['Capitalism & Corporations', 'Consumer Culture', 'Digital Culture & Technology', 'Political Economy', 'Propaganda & Social Control']::text[], true, 9, '{"sourceId":"the-system","type":"series"}'::jsonb),
('the-big-picture', 'the-big-picture', 'The Big Picture', 'Big synthesis books that connect systems, myths, presidents, thinkers, drugs, money, power, and human nature.', 'advanced', 'series', array['Cultural History', 'Government & Politics', 'Mythology & Ancient Beliefs', 'Psychology & Human Behavior', 'Political Economy']::text[], true, 10, '{"sourceId":"the-big-picture","type":"series"}'::jsonb),
('the-noisemakers', 'the-noisemakers', 'The Noisemakers', 'Musicians, performers, pop figures, and culture-shapers whose work moved through sound and spectacle.', 'starter', 'series', array['Art & Music History', 'Biography', 'Cultural History', 'Consumer Culture']::text[], true, 11, '{"sourceId":"the-noisemakers","type":"series"}'::jsonb),
('the-creatives', 'the-creatives', 'The Creatives', 'Artists, writers, filmmakers, performers, painters, and visual storytellers outside the music lane.', 'starter', 'series', array['Art & Music History', 'Biography', 'Cultural History', 'Renaissance']::text[], true, 12, '{"sourceId":"the-creatives","type":"series"}'::jsonb),
('business-as-usual', 'business-as-usual', 'Business as Usual', 'Companies, brands, industrial machines, and corporate stories that changed how people buy, eat, work, and live.', 'intermediate', 'series', array['Business & Economics', 'Capitalism & Corporations', 'Consumer Culture', 'Food & Culture']::text[], true, 13, '{"sourceId":"business-as-usual","type":"series"}'::jsonb),
('under-the-hood', 'under-the-hood', 'Under the Hood', 'Science-science: bodies, brains, physics, biology, chemistry, disease, atoms, and the mechanisms underneath experience.', 'intermediate', 'series', array['Biology & Medicine', 'Science & Mathematics', 'Science History', 'Physics & Cosmology', 'Cognitive Science & Neuroscience']::text[], true, 14, '{"sourceId":"under-the-hood","type":"series"}'::jsonb),
('the-social-code', 'the-social-code', 'The Social Code', 'Love, imagination, identity, social behavior, cultural scripts, and the human patterns people live inside.', 'intermediate', 'series', array['Psychology & Human Behavior', 'Cultural History', 'Social Movements', 'Cognitive Science & Neuroscience']::text[], true, 15, '{"sourceId":"the-social-code","type":"series"}'::jsonb),
('high-society', 'high-society', 'High Society', 'Addiction, substances, vice, medicalized dependency, dopamine loops, and the industries around them.', 'intermediate', 'series', array['Addiction & Substance Use', 'Consumer Culture', 'Psychology & Human Behavior', 'Capitalism & Corporations']::text[], true, 16, '{"sourceId":"high-society","type":"series"}'::jsonb),
('101', '101', 'JJ University 101', 'The clean introductory spine of JJ University: history, science, math, philosophy, religion, economics, government, psychology, and the hard subjects made readable.', 'intermediate', 'path', '{}'::text[], true, 17, '{"sourceId":"101-the-core-courses","type":"path"}'::jsonb),
('what-the-book-actually-says', 'what-the-book-actually-says', 'What the Scripture Actually Says', 'Direct guides through major scriptures and influential texts, focused on what the texts actually communicate rather than vague cultural assumptions.', 'intermediate', 'path', '{}'::text[], true, 18, '{"sourceId":"what-the-book-actually-says","type":"path"}'::jsonb),
('exe-power-as-code', 'exe-power-as-code', '.exe: Power as Code', 'Rulers, empires, and ideologies treated like executable programs that keep running through history.', 'intermediate', 'path', '{}'::text[], true, 19, '{"sourceId":"exe-power-as-code","type":"path"}'::jsonb),
('commanders-in-chief', 'commanders-in-chief', 'Commanders-in-Chief', 'The American presidency as biography, myth, power, and political system.', 'intermediate', 'path', '{}'::text[], true, 20, '{"sourceId":"commanders-in-chief","type":"path"}'::jsonb),
('calendar-chronicles', 'calendar-chronicles', 'Calendar Chronicles', 'The cultural history of holidays, rituals, seasonal myths, and the stories people repeat every year.', 'intermediate', 'path', '{}'::text[], true, 21, '{"sourceId":"calendar-chronicles","type":"path"}'::jsonb)
